function applyAppearance(){let a=db.settings.appearance||defaults.settings.appearance;let theme=a.theme||'classic';document.documentElement.dataset.theme=theme;document.documentElement.dataset.density=a.density||'comfortable';document.documentElement.dataset.iconPreset=a.iconPreset||'outline';if(a.customAccent)document.documentElement.style.setProperty('--accent',a.customAccent);else document.documentElement.style.setProperty('--accent',THEME_ACCENTS[theme]||THEME_ACCENTS.classic);document.querySelectorAll('[data-icon]').forEach(el=>{let key=el.dataset.icon;el.innerHTML=ICONS[key]||'';if(a.iconPreset==='bold')el.style.transform='scale(1.08)';else el.style.transform='';});if($('themeStatus'))$('themeStatus').textContent=THEMES[a.theme||'classic']?.name||'Classic';}
