function monthlyIncome(){return db.incomes.reduce((s,x)=>{let a=+x.amount||0;return s+(x.frequency==='weekly'?a*52/12:x.frequency==='biweekly'?a*26/12:x.frequency==='annual'?a/12:a)},0)}
function parseDateParts(v){let [y,m,d]=String(v||'').split('-').map(Number);return Number.isFinite(y)&&Number.isFinite(m)&&Number.isFinite(d)?new Date(y,m-1,d):null}
function dateISO(y,m,d){let x=new Date(y,m-1,d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`}
function addMonthsISO(dateStr,n){let d=parseDateParts(dateStr);if(!d)return '';let day=d.getDate(),x=new Date(d.getFullYear(),d.getMonth()+n,1),last=new Date(x.getFullYear(),x.getMonth()+1,0).getDate();return dateISO(x.getFullYear(),x.getMonth()+1,Math.min(day,last))}
function addDaysISO(dateStr,n){let d=parseDateParts(dateStr);if(!d)return '';d.setDate(d.getDate()+n);return dateISO(d.getFullYear(),d.getMonth()+1,d.getDate())}
function billStep(b){return b.frequency==='weekly'?{days:7}:b.frequency==='biweekly'?{days:14}:b.frequency==='monthly'?{months:1}:b.frequency==='quarterly'?{months:3}:b.frequency==='semiannual'?{months:6}:b.frequency==='annual'?{months:12}:{months:1}}
function nextOccurrenceDate(b,from){let start=b.startDate;if(!start)return null;let cur=start, guard=0, target=from||localDateKey(today), step=billStep(b);while(cur<target&&guard++<240){cur=step.days?addDaysISO(cur,step.days):addMonthsISO(cur,step.months)}return cur}
function occurrenceStatus(o){if(o.payments?.length||o.transactionId)return 'paid';let todayKey=localDateKey(today);if(o.dueDate<todayKey)return 'overdue';if(o.dueDate===todayKey)return 'due';return 'upcoming'}
function ensureBillOccurrences(){
  db.billOccurrences=db.billOccurrences||[];
  const existing=new Set(db.billOccurrences.map(o=>o.id));
  const min=addMonthsISO(localDateKey(today),-12), max=addMonthsISO(localDateKey(today),18);
  db.bills.forEach(b=>{if(!b.active)return;let cur=b.startDate;if(!cur)return;let guard=0,step=billStep(b);while(cur<=max&&guard++<240){if(cur>=min){let id=`bo-${b.id}-${cur}`;if(!existing.has(id)){db.billOccurrences.push({id,billId:b.id,dueDate:cur,expectedAmount:+b.expectedAmount||+b.amount||0,status:'upcoming',paidDate:null,actualAmount:null,payments:[],transactionId:null});existing.add(id)}}if(b.billType==='one-time')break;cur=step.days?addDaysISO(cur,step.days):addMonthsISO(cur,step.months)}});
  db.billOccurrences.forEach(o=>{let b=db.bills.find(x=>x.id===o.billId);if(b){o.expectedAmount=o.expectedAmount==null?(+b.expectedAmount||+b.amount||0):o.expectedAmount;o.status=occurrenceStatus(o)}});
}
function getOccurrence(id){return db.billOccurrences.find(o=>o.id===id)}
function getBill(id){return db.bills.find(b=>b.id===id)}
function occurrencePayments(o){let ids=o.payments?.length?o.payments:(o.transactionId?[o.transactionId]:[]);return ids.map(id=>db.transactions.find(t=>t.id===id)).filter(Boolean)}
function occurrencePaidAmount(o){return occurrencePayments(o).reduce((s,t)=>s+(+t.amount||0),0)}
function occurrenceDisplayStatus(o){let paid=occurrencePaidAmount(o);if(paid>0&&paid<(+o.expectedAmount||0))return 'partial';return paid>=0&&paid>=(+o.expectedAmount||0)&&paid>0?'paid':occurrenceStatus(o)}
function unpaidOccurrencesForRange(start,end){ensureBillOccurrences();return db.billOccurrences.filter(o=>o.dueDate>=start&&o.dueDate<=end&&occurrenceDisplayStatus(o)!=='paid')}
function upcomingBillOccurrences(limit=10){ensureBillOccurrences();let key=localDateKey(today);return db.billOccurrences.filter(o=>o.dueDate>=key&&occurrenceDisplayStatus(o)!=='paid').sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,limit)}
function monthlyBillTotalFor(key){let start=`${key}-01`,end=dateISO(+key.slice(0,4),+key.slice(5),new Date(+key.slice(0,4),+key.slice(5),0).getDate());return unpaidOccurrencesForRange(start,end).reduce((s,o)=>s+(+o.expectedAmount||0),0)}
function monthlyRecurringBills(){ensureBillOccurrences();let y=today.getFullYear(),m=today.getMonth()+1,start=`${y}-${String(m).padStart(2,'0')}-01`,end=dateISO(y,m,new Date(y,m,0).getDate());return db.billOccurrences.filter(o=>o.dueDate>=start&&o.dueDate<=end&&occurrenceDisplayStatus(o)!=='paid').reduce((s,o)=>s+(+o.expectedAmount||0),0)}
function dashboardOutflowsFor(key){
  const transactions=db.transactions
    .filter(x=>x.type==='expense'&&String(x.date||'').startsWith(key))
    .map(t=>{
      const occ=t.billOccurrenceId?getOccurrence(t.billOccurrenceId):null;
      const bill=occ?getBill(occ.billId):null;
      return {id:`tx-${t.id}`,txId:t.id,kind:bill?'billPayment':'transaction',name:t.payee||t.note||t.category||'Expense',category:t.category||bill?.category||'Other',amount:+t.amount||0,date:t.date,frequency:'transaction',billOccurrenceId:t.billOccurrenceId||null,billName:bill?.name||null};
    });
  return {transactions,allTransactions:transactions,bills:transactions.filter(x=>x.kind==='billPayment'),billOutflows:transactions.filter(x=>x.kind==='billPayment'),entries:transactions};
}
function txTotal(type,m=null){return db.transactions.filter(x=>x.type===type&&(!m||String(x.date||'').startsWith(m))).reduce((s,x)=>s+(+x.amount||0),0)}
function monthKeyFromDate(d){let y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0');return `${y}-${m}`}
function monthlyIncomeFor(key){return monthlyIncome()+txTotal('income',key)}
function monthlyExpenseFor(key){return dashboardOutflowsFor(key).transactions.filter(x=>x.kind!=='billPayment').reduce((s,x)=>s+(+x.amount||0),0)}
function monthlyBillFor(key){return dashboardOutflowsFor(key).transactions.filter(x=>x.kind==='billPayment').reduce((s,x)=>s+(+x.amount||0),0)}
function monthlySpendingFor(key){return monthlyExpenseFor(key)+monthlyBillFor(key)}
function monthlyAvailableFor(key){return monthlyIncomeFor(key)-monthlySpendingFor(key)}
function cashPositionHistory(){let arr=[],d=new Date(today.getFullYear(),today.getMonth()-11,1);for(let i=0;i<12;i++){let key=monthKeyFromDate(d),available=monthlyAvailableFor(key);arr.push({key,available,inc:monthlyIncomeFor(key),spent:monthlyExpenseFor(key),bills:monthlyBillFor(key)});d.setMonth(d.getMonth()+1)}return arr}
function forecast(){let arr=[],cash=+db.settings.startingCash||0,d=new Date(today.getFullYear(),today.getMonth(),1),growth=(+db.settings.incomeGrowth||0)/100;for(let i=0;i<12;i++){let key=monthKeyFromDate(d),inc=monthlyIncome()*Math.pow(1+growth,i/12)+txTotal('income',key),b=monthlyBillTotalFor(key),sp=monthlyBudget(),debt=debtPayments(),gi=goalsInvestMonthly(),net=inc-b-sp-debt-gi;cash+=net;arr.push({key,inc,b,sp,debt,gi,net,cash});d.setMonth(d.getMonth()+1)}return arr}

function canvas(id,mode,data){
  let c=$(id); if(!c)return;
  let w=Math.max(300,c.clientWidth||500),h=245,dpr=devicePixelRatio||1;
  c.width=w*dpr;c.height=h*dpr;
  let x=c.getContext('2d');x.scale(dpr,dpr);x.clearRect(0,0,w,h);x.font='12px system-ui';x.fillStyle='#667085';
  if(!data.length){x.fillText('No data yet',20,30);return}
  let pad={l:36,r:14,t:16,b:30},pw=w-pad.l-pad.r,ph=h-pad.t-pad.b;
  let vals=data.map(v=>Number(v.v??0)),max=Math.max(...vals,0),min=Math.min(...vals,0);
  if(mode!=='line'){max=Math.max(...data.map(v=>Math.max(v.v||0,v.a||0,v.b||0)),1);min=0}
  let range=Math.max(max-min,1),yFor=v=>pad.t+ph*(1-(v-min)/range),zero=yFor(0);
  x.strokeStyle='#eaecf0';
  for(let i=0;i<4;i++){let yy=pad.t+ph*i/3;x.beginPath();x.moveTo(pad.l,yy);x.lineTo(w-pad.r,yy);x.stroke()}
  if(mode==='line'){
    x.strokeStyle='#2563eb';x.lineWidth=2;x.beginPath();
    data.forEach((p,i)=>{let xx=pad.l+pw*(i/(data.length-1||1)),yy=yFor(Number(p.v)||0);i?x.lineTo(xx,yy):x.moveTo(xx,yy)});x.stroke();
    data.forEach((p,i)=>{let xx=pad.l+pw*(i/(data.length-1||1)),yy=yFor(Number(p.v)||0);x.fillStyle='#2563eb';x.beginPath();x.arc(xx,yy,4,0,7);x.fill();if(i%2===0){x.fillStyle='#667085';x.fillText(p.l,xx-13,h-9)}});
    if(min<0&&max>0){x.strokeStyle='#98a2b3';x.setLineDash([4,4]);x.beginPath();x.moveTo(pad.l,zero);x.lineTo(w-pad.r,zero);x.stroke();x.setLineDash([])}
    if(id==='dashCash'){
      c._chartData=data;c._chartMeta={pad,pw,ph,yFor,w,h};let tip=$('cashTip');
      c.onmousemove=e=>showCashTip(e,c,tip);c.onclick=e=>showCashTip(e,c,tip,true);c.onmouseleave=()=>{if(tip)tip.style.display='none'};
    }
  }else if(mode==='bars'){
    let bw=pw/data.length*.7;
    data.forEach((p,i)=>{let xx=pad.l+pw*(i+.5)/data.length,ha=ph*(p.a||0)/max,hb=ph*(p.b||0)/max;x.fillStyle='#2563eb';x.fillRect(xx-bw/2,pad.t+ph-ha,bw/2-2,ha);x.fillStyle='#98a2b3';x.fillRect(xx+2,pad.t+ph-hb,bw/2-2,hb);x.fillStyle='#667085';x.fillText(p.l,xx-10,h-9)});
  }else if(mode==='pie'){
    let total=data.reduce((s,p)=>s+(+p.v||0),0),st=-Math.PI/2;
    data.forEach((p,i)=>{let a=total?(p.v/total)*Math.PI*2:0;x.fillStyle=['#2563eb','#7f56d9','#12b76a','#f79009','#ef6820','#667085'][i%6];x.beginPath();x.moveTo(w/2,h/2);x.arc(w/2,h/2,78,st,st+a);x.closePath();x.fill();st+=a});
    if(id==='dashSpend'){
      c._chartData=data;c._chartMeta={w,h};let tip=$('spendTip');
      c.onmousemove=e=>showSpendTip(e,c,tip,false);c.onclick=e=>showSpendTip(e,c,tip,true);
      c.ontouchend=e=>{let t=e.changedTouches?.[0];if(t)showSpendTip({clientX:t.clientX,clientY:t.clientY},c,tip,true)};
      c.onmouseleave=()=>{if(tip)tip.style.display='none'};
    }
  }
}
function showCashTip(e,c,tip,keep){if(!tip||!c._chartData)return;let r=c.getBoundingClientRect(),mx=e.clientX-r.left,meta=c._chartMeta,idx=Math.max(0,Math.min(c._chartData.length-1,Math.round((mx-meta.pad.l)/meta.pw*(c._chartData.length-1))));let p=c._chartData[idx];let rows=`<strong>${esc(p.label||p.key)}</strong><div class="tiprow"><span>Income</span><b>${money(p.inc)}</b></div><div class="tiprow"><span>Expenses</span><b>${money(p.spent)}</b></div><div class="tiprow"><span>Bills</span><b>${money(p.bills)}</b></div><div class="tiprow tipsave"><span>${p.available>=0?'Saved':'Shortfall'}</span><b class="${p.available>=0?'good':'bad'}">${p.available>=0?'+':''}${money(p.available)}</b></div>`;tip.innerHTML=rows;let xx=meta.pad.l+meta.pw*(idx/(c._chartData.length-1||1));tip.style.display='block';tip.style.left=Math.max(6,Math.min(meta.w-186,xx-90))+'px';tip.style.top=Math.max(6,meta.yFor(p.available)-65)+'px';if(!keep)tip._hover=true}
function showSpendTip(e,c,tip,keep){if(!tip||!c._chartData?.length)return;let r=c.getBoundingClientRect(),mx=e.clientX-r.left,my=e.clientY-r.top,cx=c.clientWidth/2,cy=c.clientHeight/2,dx=mx-cx,dy=my-cy,dist=Math.sqrt(dx*dx+dy*dy);if(dist>82||dist<24){if(!keep)tip.style.display='none';return}let angle=Math.atan2(dy,dx)+Math.PI/2;if(angle<0)angle+=Math.PI*2;let total=c._chartData.reduce((s,p)=>s+(+p.v||0),0),cursor=0,idx=-1;for(let i=0;i<c._chartData.length;i++){let sweep=total?(c._chartData[i].v/total)*Math.PI*2:0;if(angle>=cursor&&angle<cursor+sweep){idx=i;break}cursor+=sweep}if(idx<0)return;let p=c._chartData[idx],pct=total?(p.v/total)*100:0;tip.innerHTML=`<strong>${esc(p.l)}</strong><div class="tiprow"><span>Total</span><b>${money(p.v)}</b></div><div class="tiprow"><span>Share of spending</span><b>${pct.toFixed(1)}%</b></div>`;tip.style.display='block';tip.style.left=Math.max(6,Math.min(c.clientWidth-180,mx+12))+'px';tip.style.top=Math.max(6,Math.min(c.clientHeight-78,my-12))+'px';tip._selected=keep?idx:null}

function comparisonPct(current,previous){if(previous===null||previous===undefined||!Number.isFinite(previous)||Math.abs(previous)<0.000001)return null;if(!Number.isFinite(current))return null;if(current!==0&&previous!==0&&((current<0)!=(previous<0)))return null;return (current-previous)/Math.abs(previous)*100}
function monthOffsetKey(offset){let d=new Date(today.getFullYear(),today.getMonth()+offset,1);return monthKeyFromDate(d)}
function quarterValue(monthsBack,metric){let end=new Date(today.getFullYear(),today.getMonth()-monthsBack,1),start=new Date(end.getFullYear(),end.getMonth()-2,1),sum=0;for(let i=0;i<3;i++){let k=monthKeyFromDate(new Date(start.getFullYear(),start.getMonth()+i,1));sum+=metric(k)}return sum}
