function periodEnd(kind){if(kind==='month')return localDateKey(new Date(today.getFullYear(),today.getMonth(),0));if(kind==='quarter'){let qStart=Math.floor(today.getMonth()/3)*3;return localDateKey(new Date(today.getFullYear(),qStart,0));}return `${today.getFullYear()-1}-12-31`}
