  $('modalForm').innerHTML=`<div>${items.map(o=>{const b=getBill(o.billId),st=occurrenceDisplayStatus(o);return `<div class=\"listrow\"><button type=\"button\" class=\"billDashLink\" onclick=\"closeModal();showBillOccurrence('${o.id}')\"><span><b>${esc(b?.name||'Bill')}</b><br><span class=\"mini\">Expected ${money(o.expectedAmount)} · ${billStatusHtml(st)}</span></span></button>${st==='paid'?`<span>${money(occurrencePaidAmount(o))}</span>`:`<button type=\"button\" class=\"btn small primary\" onclick=\"closeModal();openPaymentModal('${o.id}')\">Mark Paid</button>`}</div>`}).join('')}</div>`;
