function openPaymentModal(occId){ensureBillOccurrences();let o=getOccurrence(occId),b=o&&getBill(o.billId);if(!o||!b)return;let paid=occurrencePaidAmount(o),remaining=Math.max(0,(+o.expectedAmount||0)-paid),todayKey=localDateKey(today);if(occurrenceDisplayStatus(o)==='paid'){showBillOccurrence(occId);return}$('modalTitle').textContent=paid?'Add payment':'Mark bill paid';$('modalForm').innerHTML=`<div class="formgrid">${f('Bill','billName','text',b.name,'readonly')}${f('Payment date','date','date',todayKey,'required')}${f('Actual amount','amount','number',remaining||o.expectedAmount,'required min="0.01" step=".01"')}${f('Payment account','account','text','','placeholder="Checking"')}${s('Category','category',db.categories,b.category||'Other')}${f('Payment note','note')}<div class="full"><div class="notice">Due ${dateText(o.dueDate)} · Expected ${money(o.expectedAmount)} · Already paid ${money(paid)}. This creates one Transaction linked to this bill occurrence.</div></div><div class="full"><button class="btn primary" type="submit">Save payment</button></div></div>`;$('modalForm').dataset.type='payment';$('modalForm').dataset.occurrenceId=occId;$('modalBack').classList.add('show')}
function deleteTransaction(id){let t=db.transactions.find(x=>x.id===id);if(!t)return;if(!confirm('Delete this transaction? If it is linked to a bill, that bill will become unpaid again.'))return;db.transactions=db.transactions.filter(x=>x.id!==id);if(t.billOccurrenceId){let o=getOccurrence(t.billOccurrenceId);if(o){o.payments=(o.payments||[]).filter(x=>x!==id);if(o.transactionId===id)o.transactionId=o.payments?.[0]||null;let remaining=occurrencePaidAmount(o);let remainingPayments=occurrencePayments(o);o.paidDate=remainingPayments.length?remainingPayments[remainingPayments.length-1].date:null;o.actualAmount=remaining||null;o.status=occurrenceDisplayStatus(o)}}save();render()}
function linkTransactionToBill(txId,occId){let t=db.transactions.find(x=>x.id===txId),o=getOccurrence(occId);if(!t||!o)return;if(t.type!=='expense'){alert('Only expense transactions can be linked to a bill.');return}if(occurrenceDisplayStatus(o)==='paid'){alert('This bill occurrence is already fully paid.');return}if(t.billOccurrenceId&&t.billOccurrenceId!==occId){alert('This transaction is already linked to another bill.');return}t.billOccurrenceId=occId;o.payments=o.payments||[];if(!o.payments.includes(txId))o.payments.push(txId);o.transactionId=o.payments[0]||null;o.paidDate=t.date;o.actualAmount=occurrencePaidAmount(o);o.status=occurrenceDisplayStatus(o);save();render()}

function renderBudgets(){let m=currentMonth();$('budgetList').innerHTML=db.budgets.map(b=>{let actual=db.transactions.filter(t=>t.type==='expense'&&t.category===b.category&&t.date.startsWith(m)).reduce((s,t)=>s+ +t.amount,0),p=b.limit?Math.min(100,actual/b.limit*100):0;return `<div class="card"><div class="sectionhead"><b>${esc(b.category)}</b><button class="btn small danger" onclick="remove('budgets','${b.id}')">Delete</button></div><div class="label">${money(actual)} of ${money(b.limit)}</div><div class="progress section"><div class="bar" style="width:${p}%"></div></div><div class="mini section">${p.toFixed(0)}% used</div></div>`}).join('')||'<div class="empty">Create a budget category.</div>'}
function renderDebts(){let bal=db.debts.reduce((s,x)=>s+ +x.balance,0),pay=debtPayments(),interest=db.debts.reduce((s,x)=>s+ +payoff(x).interest,0);$('debtCards').innerHTML=[['Debt balance',money(bal)],['Monthly payment',money(pay)],['Projected interest',money(interest)],['Accounts',db.debts.length]].map(a=>`<div class="card"><div class="label">${a[0]}</div><div class="metric">${a[1]}</div></div>`).join('');$('debtTable').innerHTML=db.debts.map(d=>{let p=payoff(d);return `<tr><td><b>${esc(d.name)}</b><br><span class="mini">${esc(d.type)}</span></td><td>${money(d.balance)}</td><td>${(+d.apr).toFixed(2)}%</td><td>${money(d.minimum)}</td><td>${money(d.extra)}</td><td>${p.date}</td><td>${money(p.interest)}</td><td>${historyButton('debts',d.id)} <button class="btn small danger" onclick="remove('debts','${d.id}')">Delete</button></td></tr>`}).join('')||'<tr><td colspan="8" class="empty">No debts.</td></tr>';canvas('debtChart','line',db.debts.map(d=>({l:d.name.slice(0,9),v:d.balance})));$('strategy').innerHTML=`<div class="notice">Avalanche focuses extra payments on higher APR balances; snowball focuses extra payments on smaller balances. This app records the inputs and payoff math so you can compare them without changing your accounts.</div>`}
function renderGoals(){ $('goalList').innerHTML=db.goals.map(g=>{let p=g.target?Math.min(100,g.saved/g.target*100):0;return `<div class="card"><div class="sectionhead"><b>${esc(g.name)}</b><span>${historyButton('goals',g.id)} <button class="btn small danger" onclick="remove('goals','${g.id}')">Delete</button></span></div><div class="label">${money(g.saved)} of ${money(g.target)}${g.date?' · '+dateText(g.date):''}</div><div class="progress section"><div class="bar" style="width:${p}%"></div></div><div class="split section mini"><span>${p.toFixed(0)}%</span><span>${money(Math.max(0,g.target-g.saved))} remaining</span></div></div>`}).join('')||'<div class="empty">No goals.</div>'}
function renderNetworth(){let a=db.assets.reduce((s,x)=>s+ +x.value,0),l=db.liabilities.reduce((s,x)=>s+ +x.value,0)+db.debts.reduce((s,x)=>s+ +x.balance,0);$('nwCards').innerHTML=[['Assets',money(a)],['Liabilities',money(l)],['Net worth',money(a-l),a-l>=0?'good':'bad'],['Investments',money(db.investments.reduce((s,x)=>s+ +x.balance,0))]].map(x=>`<div class="card"><div class="label">${x[0]}</div><div class="metric ${x[2]||''}">${x[1]}</div></div>`).join('');$('assetList').innerHTML=db.assets.map(x=>`<div class="listrow"><span>${esc(x.name)}<br><span class="mini">${esc(x.type)}</span></span><span><b>${money(x.value)}</b> ${historyButton('assets',x.id)} <button class="btn small danger" onclick="remove('assets','${x.id}')">×</button></span></div>`).join('')||'<div class="empty">No assets.</div>';$('liabilityList').innerHTML=db.liabilities.map(x=>`<div class="listrow"><span>${esc(x.name)}<br><span class="mini">${esc(x.type)}</span></span><span><b>${money(x.value)}</b> ${historyButton('liabilities',x.id)} <button class="btn small danger" onclick="remove('liabilities','${x.id}')">×</button></span></div>`).join('')||'<div class="empty">No extra liabilities. Debts are shown in debt payoff.</div>'}
function renderInvestments(){let total=db.investments.reduce((s,x)=>s+ +x.balance,0),monthly=db.investments.reduce((s,x)=>s+ +x.monthly,0);$('invCards').innerHTML=[['Invested balance',money(total)],['Monthly contributions',money(monthly)],['Accounts',db.investments.length]].map(x=>`<div class="card"><div class="label">${x[0]}</div><div class="metric">${x[1]}</div></div>`).join('');$('invTable').innerHTML=db.investments.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.type)}</td><td>${money(x.balance)}</td><td>${money(x.monthly)}</td><td>${esc(x.allocation||'Not set')}</td><td>${historyButton('investments',x.id)} <button class="btn small danger" onclick="remove('investments','${x.id}')">Delete</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No investment accounts.</td></tr>'}
function renderReports(){let p=forecast();$('reportCards').innerHTML=[['12-month income',money(p.reduce((s,x)=>s+x.inc,0))],['12-month outflow',money(p.reduce((s,x)=>s+x.b+x.sp+x.debt+x.gi,0))],['12-month net',money(p.reduce((s,x)=>s+x.net,0))],['Ending cash',money(p[p.length-1]?.cash||0)]].map(x=>`<div class="card"><div class="label">${x[0]}</div><div class="metric">${x[1]}</div></div>`).join('');canvas('incomeOutChart','bars',p.map(x=>({l:x.key.slice(5),a:x.inc,b:x.b+x.sp+x.debt+x.gi})));canvas('projectionChart','line',p.map(x=>({l:x.key.slice(5),v:x.cash})));$('forecastTable').innerHTML=p.map(x=>`<tr><td>${x.key}</td><td>${money(x.inc)}</td><td>${money(x.b)}</td><td>${money(x.sp)}</td><td>${money(x.debt)}</td><td>${money(x.gi)}</td><td class="${x.net>=0?'good':'bad'}">${money(x.net)}</td><td>${money(x.cash)}</td></tr>`).join('')}
function yearOf(date){return String(date||'').slice(0,4)}
function annualYears(){let years=new Set([String(today.getFullYear())]);[...db.transactions,...db.paychecks,...db.bills].forEach(x=>{if(x.date)years.add(yearOf(x.date))});return [...years].filter(Boolean).sort().reverse()}
function annualBillAmount(b,y){ensureBillOccurrences();let start=`${y}-01-01`,end=`${y}-12-31`;return db.billOccurrences.filter(o=>o.dueDate>=start&&o.dueDate<=end).reduce((s,o)=>s+(+o.expectedAmount||0),0)}
function annualData(y){let tx=db.transactions,earned=tx.filter(t=>t.type==='income'&&t.date.startsWith(y)).reduce((s,t)=>s+(+t.amount||0),0),spent=tx.filter(t=>t.type==='expense'&&t.date.startsWith(y)).reduce((s,t)=>s+(+t.amount||0),0),expenseCats={},incomeCats={};tx.filter(t=>t.date.startsWith(y)).forEach(t=>{let k=t.category||'Other',a=+t.amount||0;if(t.type==='expense')expenseCats[k]=(expenseCats[k]||0)+a;if(t.type==='income')incomeCats[k]=(incomeCats[k]||0)+a});let quarters=[1,2,3,4].map(q=>{let months=[q*3-2,q*3-1,q*3].map(n=>String(n).padStart(2,'0')),e=tx.filter(t=>t.type==='income'&&months.some(m=>t.date.startsWith(`${y}-${m}`))).reduce((s,t)=>s+(+t.amount||0),0),sp=tx.filter(t=>t.type==='expense'&&months.some(m=>t.date.startsWith(`${y}-${m}`))).reduce((s,t)=>s+(+t.amount||0),0),debt=tx.filter(t=>t.type==='expense'&&(t.category==='Debt Payment'||/debt|loan|credit/i.test(t.category||''))&&months.some(m=>t.date.startsWith(`${y}-${m}`))).reduce((s,t)=>s+(+t.amount||0),0);return{q:`Q${q}`,earned:e,spent:sp,saved:e-sp,rate:e?((e-sp)/e*100):0,debt}});let months=Array.from({length:12},(_,i)=>{let m=String(i+1).padStart(2,'0'),prefix=`${y}-${m}`,e=tx.filter(t=>t.date.startsWith(prefix)&&t.type==='income').reduce((s,t)=>s+(+t.amount||0),0),sp=tx.filter(t=>t.date.startsWith(prefix)&&t.type==='expense').reduce((s,t)=>s+(+t.amount||0),0),debt=tx.filter(t=>t.date.startsWith(prefix)&&t.type==='expense'&&(t.category==='Debt Payment'||/debt|loan|credit/i.test(t.category||''))).reduce((s,t)=>s+(+t.amount||0),0);let bills=db.billOccurrences.filter(o=>o.dueDate.startsWith(prefix)).reduce((s,o)=>s+(+o.expectedAmount||0),0);return{m,label:new Date(+y,i,1).toLocaleDateString(undefined,{month:'short'}),earned:e,spent:sp,net:e-sp,bills,debt}});let bills=db.bills.map(b=>({name:b.name,amount:annualBillAmount(b,y),category:b.category})).filter(x=>x.amount>0).sort((a,b)=>b.amount-a.amount);return{tx,earned,spent,net:earned-spent,expenseCats,incomeCats,months,quarters,bills,totalBills:bills.reduce((s,x)=>s+x.amount,0)}}
function renderAnnual(){
 let years=annualYears(), sel=$('annualYear'), current=String(today.getFullYear());
 if(sel){let old=sel.value;sel.innerHTML=years.map(y=>`<option value="${y}">${y}</option>`).join('');sel.value=years.includes(old)?old:current;}
 let y=sel?.value||current,d=annualData(y),savingRate=d.earned?d.net/d.earned*100:0;
 $('annualCards').innerHTML=[['Earned income',money(d.earned),''],['Actual spending',money(d.spent),''],['Net retained',money(d.net),d.net>=0?'good':'bad'],['Planned annual bills',money(d.totalBills),'']].map(a=>`<div class="card"><div class="label">${a[0]}</div><div class="metric ${a[2]}">${a[1]}</div></div>`).join('');
 $('annualIncomeNote').textContent=`${Object.keys(d.incomeCats).length} income source${Object.keys(d.incomeCats).length===1?'':'s'}`;
 $('annualExpenseNote').textContent=`${Object.keys(d.expenseCats).length} spending categor${Object.keys(d.expenseCats).length===1?'y':'ies'}`;
 canvas('annualIncomeChart','pie',Object.entries(d.incomeCats).sort((a,b)=>b[1]-a[1]).slice(0,7).map(x=>({l:x[0],v:x[1]})));
 canvas('annualExpenseChart','pie',Object.entries(d.expenseCats).sort((a,b)=>b[1]-a[1]).slice(0,7).map(x=>({l:x[0],v:x[1]})));
 canvas('annualBillsChart','bars',d.bills.slice(0,10).map(x=>({l:x.name.slice(0,12),a:x.amount})));
 canvas('annualQuarterChart','bars',d.quarters.map(x=>({l:x.q,a:x.earned,b:x.spent})));
 canvas('annualMonthlyChart','bars',d.months.map(x=>({l:x.label,a:x.earned,b:x.spent})));
 $('annualQuarterTable').innerHTML=d.quarters.map(x=>`<tr><td><b>${x.q}</b></td><td class="good">${money(x.earned)}</td><td class="bad">${money(x.spent)}</td><td class="${x.saved>=0?'good':'bad'}">${money(x.saved)}</td><td>${x.rate.toFixed(1)}%</td><td>${money(x.debt)}</td></tr>`).join('');
 $('annualMonthTable').innerHTML=d.months.map(x=>`<tr><td><b>${x.label}</b></td><td class="good">${money(x.earned)}</td><td class="bad">${money(x.spent)}</td><td class="${x.net>=0?'good':'bad'}">${money(x.net)}</td><td>${money(x.bills)}</td><td>${money(x.debt)}</td></tr>`).join('');
 $('annualDebtList').innerHTML=db.debts.slice().sort((a,b)=>+b.balance-+a.balance).map(x=>{let p=payoff(x);return `<div class="listrow"><span><b>${esc(x.name)}</b><br><span class="mini">${(+x.apr).toFixed(2)}% APR · ${p.date}</span></span><b>${money(x.balance)}</b></div>`}).join('')||'<div class="empty">No debt accounts added.</div>';
}
$('annualYear')?.addEventListener('change',renderAnnual);$('annualThisYear')?.addEventListener('click',()=>{if($('annualYear')){$('annualYear').value=String(today.getFullYear());renderAnnual()}});
function renderData(){$('appVersion').value=APP_VERSION;$('updateLastChecked').value=db.settings.updates?.lastChecked?new Date(db.settings.updates.lastChecked).toLocaleString():'Never';$('autoUpdates').checked=db.settings.updates?.auto!==false;$('updateStatus').textContent='Current';$('currency').value=db.settings.currency;$('startCash').value=db.settings.startingCash;$('saveTarget').value=db.settings.saveTarget;$('incomeGrowth').value=db.settings.incomeGrowth;renderAppearanceSettings();if($('supabaseUrl'))$('supabaseUrl').value=db.settings.sync?.url||'';if($('supabaseKey'))$('supabaseKey').value=db.settings.sync?.key||'';if($('syncEmail'))$('syncEmail').value=db.settings.sync?.email||'';}
function render(){let p=document.querySelector('.page.active')?.id||'dashboard';if(p==='dashboard')renderDashboard();if(p==='annual')renderAnnual();if(p==='plan')renderPlan();if(p==='transactions')renderTransactions();if(p==='bills')renderBills();if(p==='budgets')renderBudgets();if(p==='debts')renderDebts();if(p==='goals')renderGoals();if(p==='networth')renderNetworth();if(p==='investments')renderInvestments();if(p==='reports')renderReports();if(p==='data')renderData()}
function addHistoryEvent(type,id){let item=db[type]?.find(x=>x.id===id);if(!item)return;let valueField=type==='goals'?'saved':type==='investments'?'balance':type==='debts'?'balance':type==='liabilities'||type==='assets'?'value':null;if(!valueField)return;let titleMap={goals:'Savings',investments:'Investment',debts:'Debt',liabilities:'Liability',assets:'Asset'};let value=+item[valueField]||0;let date=localDateKey(today);let body=`<div class="formgrid">${f('Effective date','date','date',date,'required')}${f('Balance / value', 'value','number',value,'required min="0" step=".01"')}<div class="full"><div class="notice">This records a historical point for ${titleMap[type]||'account'}. Use a past date if you know what the balance/value was then.</div></div><div class="full"><button class="btn primary" type="submit">Record history</button></div></div>`;$('modalTitle').textContent=`Record ${titleMap[type]||'balance'} history`;$('modalForm').innerHTML=body;$('modalForm').dataset.type='history';$('modalForm').dataset.historyType=type;$('modalForm').dataset.historyId=id;$('modalBack').classList.add('show')}
function historyButton(type,id){return `<button class="btn small" onclick="addHistoryEvent('${type}','${id}')">History</button>`}
function remove(type,id){db[type]=db[type].filter(x=>x.id!==id);save();render()}

function f(label,name,type='text',value='',extra=''){return `<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function s(label,name,opts,value=''){return `<div class="field"><label>${label}</label><select name="${name}">${opts.map(o=>`<option value="${esc(o)}" ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`}
function unpaidBillOptions(){ensureBillOccurrences();return db.billOccurrences.filter(o=>occurrenceDisplayStatus(o)!=='paid').sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,150)}
function refreshBillFormVisibility(){let form=$('modalForm');if(!form||!['bill','billEdit'].includes(form.dataset.type))return;let bt=form.querySelector('[name="billType"]')?.value,at=form.querySelector('[name="amountType"]')?.value;let freq=form.querySelector('[name="frequency"]')?.closest('.field');if(freq)freq.style.display=bt==='one-time'?'none':'';let notice=form.querySelector('.notice');if(notice)notice.textContent=at==='variable'?'Expected amount is a planning estimate. The actual payment amount is recorded when the bill is paid.':'Fixed bills still allow the actual payment amount to be edited when paid. Changes to an existing bill apply to future unpaid occurrences; paid history and transactions stay unchanged.'}
function closeModal(){
  const back=$('modalBack');
  const form=$('modalForm');
  if(back)back.classList.remove('show');
  if(form){form.reset?.();form.innerHTML='';delete form.dataset.type;delete form.dataset.editId;delete form.dataset.occurrenceId;delete form.dataset.historyType;delete form.dataset.historyId;}
  if($('modalTitle'))$('modalTitle').textContent='';
}
window.closeModal=closeModal;
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('modalBack')?.classList.contains('show'))closeModal()});

